 (source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,tested_topic,law_version_checked_at)
select s.id,'f4cf30c7-c88d-4b7a-87aa-a4be5ccea266',v.k,'Apostila de informática — repertório de concursos anteriores (banca não identificada)',2026,'Repertório para concursos','NÃO IDENTIFICADA','Informática',v.sub,v.txt,v.ans,v.expl,v.basis,'média','active',false,v.top,v.chk
